23	import { IEditorWorkerService } from '../../../common/services/editorWorker.js';
24	import { IResolvedTextEditorModel, ITextModelService } from '../../../common/services/resolverService.js';
25	import { FormattingEdit } from './formattingEdit.js';
26	import { CommandsRegistry } from '../../../../platform/commands/common/commands.js';
27	import { ExtensionIdentifierSet } from '../../../../platform/extensions/common/extensions.js';
28	import { IInstantiationService } from '../../../../platform/instantiation/common/instantiation.js';
29	import { IProgress } from '../../../../platform/progress/common/progress.js';
30	import { ILanguageFeaturesService } from '../../../common/services/languageFeatures.js';
31	import { LanguageFeatureRegistry } from '../../../common/languageFeatureRegistry.js';
32	import { ILogService } from '../../../../platform/log/common/log.js';
33	import { AccessibilitySignal, IAccessibilitySignalService } from '../../../../platform/accessibilitySignal/browser/accessibilitySignalService.js';
34	
35	export function getRealAndSyntheticDocumentFormattersOrdered(
36		documentFormattingEditProvider: LanguageFeatureRegistry<DocumentFormattingEditProvider>,
37		documentRangeFormattingEditProvider: LanguageFeatureRegistry<DocumentRangeFormattingEditProvider>,
38		model: ITextModel
39	): DocumentFormattingEditProvider[] {
40		const result: DocumentFormattingEditProvider[] = [];
41		const seen = new ExtensionIdentifierSet();
42	
43		// (1) add all document formatter
44		const docFormatter = documentFormattingEditProvider.ordered(model);
45		for (const formatter of docFormatter) {
46			result.push(formatter);
47			if (formatter.extensionId) {
48				seen.add(formatter.extensionId);
49			}
50		}
51	
52		// (2) add all range formatter as document formatter (unless the same extension already did that)
53		const rangeFormatter = documentRangeFormattingEditProvider.ordered(model);
54		for (const formatter of rangeFormatter) {
55			if (formatter.extensionId) {
56				if (seen.has(formatter.extensionId)) {
57					continue;
58				}
59				seen.add(formatter.extensionId);
60			}
61			result.push({
62				displayName: formatter.displayName,
63				extensionId: formatter.extensionId,
64				provideDocumentFormattingEdits(model, options, token) {
65					return formatter.provideDocumentRangeFormattingEdits(model, model.getFullModelRange(), options, token);
66				}
67			});
68		}
69		return result;
70	}
71	
72	export const enum FormattingKind {
73		File = 1,
74		Selection = 2
75	}
76	
77	export const enum FormattingMode {
78		Explicit = 1,
79		Silent = 2
80	}
