107	export async function formatDocumentRangesWithSelectedProvider(
108		accessor: ServicesAccessor,
109		editorOrModel: ITextModel | IActiveCodeEditor,
110		rangeOrRanges: Range | Range[],
111		mode: FormattingMode,
112		progress: IProgress<DocumentRangeFormattingEditProvider>,
113		token: CancellationToken,
114		userGesture: boolean
115	): Promise<void> {
116	
117		const instaService = accessor.get(IInstantiationService);
118		const { documentRangeFormattingEditProvider: documentRangeFormattingEditProviderRegistry } = accessor.get(ILanguageFeaturesService);
119		const model = isCodeEditor(editorOrModel) ? editorOrModel.getModel() : editorOrModel;
120		const provider = documentRangeFormattingEditProviderRegistry.ordered(model);
121		const selected = await FormattingConflicts.select(provider, model, mode, FormattingKind.Selection);
122		if (selected) {
123			progress.report(selected);
124			await instaService.invokeFunction(formatDocumentRangesWithProvider, selected, editorOrModel, rangeOrRanges, token, userGesture);
125		}
126	}
127	
128	export async function formatDocumentRangesWithProvider(
129		accessor: ServicesAccessor,
130		provider: DocumentRangeFormattingEditProvider,
131		editorOrModel: ITextModel | IActiveCodeEditor,
132		rangeOrRanges: Range | Range[],
133		token: CancellationToken,
134		userGesture: boolean
135	): Promise<boolean> {
136		const workerService = accessor.get(IEditorWorkerService);
137		const logService = accessor.get(ILogService);
138		const accessibilitySignalService = accessor.get(IAccessibilitySignalService);
139	
140		let model: ITextModel;
141		let cts: CancellationTokenSource;
142		if (isCodeEditor(editorOrModel)) {
143			model = editorOrModel.getModel();
144			cts = new EditorStateCancellationTokenSource(editorOrModel, CodeEditorStateFlag.Value | CodeEditorStateFlag.Position, undefined, token);
145		} else {
146			model = editorOrModel;
147			cts = new TextModelCancellationTokenSource(editorOrModel, token);
148		}
149	
150		// make sure that ranges don't overlap nor touch each other
151		const ranges: Range[] = [];
152		let len = 0;
153		for (const range of asArray(rangeOrRanges).sort(Range.compareRangesUsingStarts)) {
154			if (len > 0 && Range.areIntersectingOrTouching(ranges[len - 1], range)) {
155				ranges[len - 1] = Range.fromPositions(ranges[len - 1].getStartPosition(), range.getEndPosition());
156			} else {
157				len = ranges.push(range);
158			}
159		}
160	
161		const computeEdits = async (range: Range) => {
162			logService.trace(`[format][provideDocumentRangeFormattingEdits] (request)`, provider.extensionId?.value, range);
163	
164			const result = (await provider.provideDocumentRangeFormattingEdits(
165				model,
166				range,
167				model.getFormattingOptions(),
168				cts.token
169			)) || [];
170	
171			logService.trace(`[format][provideDocumentRangeFormattingEdits] (response)`, provider.extensionId?.value, result);
172	
173			return result;
174		};
175	
176		const hasIntersectingEdit = (a: TextEdit[], b: TextEdit[]) => {
177			if (!a.length || !b.length) {
178				return false;
179			}
180			// quick exit if the list of ranges are completely unrelated [O(n)]
181			const mergedA = a.reduce((acc, val) => { return Range.plusRange(acc, val.range); }, a[0].range);
182			if (!b.some(x => { return Range.intersectRanges(mergedA, x.range); })) {
183				return false;
184			}
185			// fallback to a complete check [O(n^2)]
186			for (const edit of a) {
187				for (const otherEdit of b) {
188					if (Range.intersectRanges(edit.range, otherEdit.range)) {
189						return true;
190					}
191				}
192			}
193			return false;
194		};
195	
196		const allEdits: TextEdit[] = [];
197		const rawEditsList: TextEdit[][] = [];
198		try {
199			if (typeof provider.provideDocumentRangesFormattingEdits === 'function') {
200				logService.trace(`[format][provideDocumentRangeFormattingEdits] (request)`, provider.extensionId?.value, ranges);
201				const result = (await provider.provideDocumentRangesFormattingEdits(
202					model,
203					ranges,
204					model.getFormattingOptions(),
205					cts.token
206				)) || [];
207				logService.trace(`[format][provideDocumentRangeFormattingEdits] (response)`, provider.extensionId?.value, result);
208				rawEditsList.push(result);
209			} else {
210	
211				for (const range of ranges) {
212					if (cts.token.isCancellationRequested) {
213						return true;
214					}
215					rawEditsList.push(await computeEdits(range));
216				}
217	
218				for (let i = 0; i < ranges.length; ++i) {
219					for (let j = i + 1; j < ranges.length; ++j) {
220						if (cts.token.isCancellationRequested) {
221							return true;
222						}
223						if (hasIntersectingEdit(rawEditsList[i], rawEditsList[j])) {
224							// Merge ranges i and j into a single range, recompute the associated edits
225							const mergedRange = Range.plusRange(ranges[i], ranges[j]);
226							const edits = await computeEdits(mergedRange);
227							ranges.splice(j, 1);
228							ranges.splice(i, 1);
229							ranges.push(mergedRange);
230							rawEditsList.splice(j, 1);
231							rawEditsList.splice(i, 1);
232							rawEditsList.push(edits);
233							// Restart scanning
234							i = 0;
235							j = 0;
236						}
237					}
238				}
239			}
240	
241			for (const rawEdits of rawEditsList) {
242				if (cts.token.isCancellationRequested) {
243					return true;
244				}
245				const minimalEdits = await workerService.computeMoreMinimalEdits(model.uri, rawEdits);
246				if (minimalEdits) {
247					allEdits.push(...minimalEdits);
248				}
249			}
250	
251			if (cts.token.isCancellationRequested) {
252				return true;
253			}
254		} finally {
255			cts.dispose();
256		}
257	
258		if (allEdits.length === 0) {
259			return false;
260		}
261	
262		if (isCodeEditor(editorOrModel)) {
263			// use editor to apply edits
264			FormattingEdit.execute(editorOrModel, allEdits, true);
265			editorOrModel.revealPositionInCenterIfOutsideViewport(editorOrModel.getPosition(), ScrollType.Immediate);
266	
267		} else {
268			// use model to apply edits
269			const [{ range }] = allEdits;
270			const initialSelection = new Selection(range.startLineNumber, range.startColumn, range.endLineNumber, range.endColumn);
271			model.pushEditOperations([initialSelection], allEdits.map(edit => {
272				return {
273					text: edit.text,
274					range: Range.lift(edit.range),
275					forceMoveMarkers: true
276				};
277			}), undoEdits => {
278				for (const { range } of undoEdits) {
279					if (Range.areIntersectingOrTouching(range, initialSelection)) {
280						return [new Selection(range.startLineNumber, range.startColumn, range.endLineNumber, range.endColumn)];
281					}
282				}
283				return null;
284			});
285		}
286		accessibilitySignalService.playSignal(AccessibilitySignal.format, { userGesture });
287		return true;
288	}
