384	export async function getDocumentRangeFormattingEditsUntilResult(
385		workerService: IEditorWorkerService,
386		languageFeaturesService: ILanguageFeaturesService,
387		model: ITextModel,
388		range: Range,
389		options: FormattingOptions,
390		token: CancellationToken
391	): Promise<TextEdit[] | undefined> {
392	
393		const providers = languageFeaturesService.documentRangeFormattingEditProvider.ordered(model);
394		for (const provider of providers) {
395			const rawEdits = await Promise.resolve(provider.provideDocumentRangeFormattingEdits(model, range, options, token)).catch(onUnexpectedExternalError);
396			if (isNonEmptyArray(rawEdits)) {
397				return await workerService.computeMoreMinimalEdits(model.uri, rawEdits);
398			}
399		}
400		return undefined;
401	}
