469	CommandsRegistry.registerCommand('_executeFormatRangeProvider', async function (accessor, ...args) {
470		const [resource, range, options] = args;
471		assertType(URI.isUri(resource));
472		assertType(Range.isIRange(range));
473	
474		const resolverService = accessor.get(ITextModelService);
475		const workerService = accessor.get(IEditorWorkerService);
476		const languageFeaturesService = accessor.get(ILanguageFeaturesService);
477		const reference = await resolverService.createModelReference(resource);
478		try {
479			return getDocumentRangeFormattingEditsUntilResult(workerService, languageFeaturesService, reference.object.textEditorModel, Range.lift(range), ensureFormattingOptions(options, reference), CancellationToken.None);
480		} finally {
481			reference.dispose();
482		}
483	});
484	
485	CommandsRegistry.registerCommand('_executeFormatDocumentProvider', async function (accessor, ...args) {
486		const [resource, options] = args;
487		assertType(URI.isUri(resource));
488	
489		const resolverService = accessor.get(ITextModelService);
490		const workerService = accessor.get(IEditorWorkerService);
491		const languageFeaturesService = accessor.get(ILanguageFeaturesService);
492		const reference = await resolverService.createModelReference(resource);
493		try {
494			return getDocumentFormattingEditsUntilResult(workerService, languageFeaturesService, reference.object.textEditorModel, ensureFormattingOptions(options, reference), CancellationToken.None);
495		} finally {
496			reference.dispose();
497		}
498	});
499	
500	CommandsRegistry.registerCommand('_executeFormatOnTypeProvider', async function (accessor, ...args) {
501		const [resource, position, ch, options] = args;
502		assertType(URI.isUri(resource));
503		assertType(Position.isIPosition(position));
504		assertType(typeof ch === 'string');
505	
506		const resolverService = accessor.get(ITextModelService);
507		const workerService = accessor.get(IEditorWorkerService);
508		const languageFeaturesService = accessor.get(ILanguageFeaturesService);
509		const reference = await resolverService.createModelReference(resource);
510		try {
511			return getOnTypeFormattingEdits(workerService, languageFeaturesService, reference.object.textEditorModel, Position.lift(position), ch, ensureFormattingOptions(options, reference), CancellationToken.None);
512		} finally {
513			reference.dispose();
514		}
515	});
516	function ensureFormattingOptions(options: unknown, reference: IReference<IResolvedTextEditorModel>): FormattingOptions {
517		let validatedOptions: FormattingOptions;
518		if (isFormattingOptions(options)) {
519			validatedOptions = options;
520		} else {
521			const modelOptions = reference.object.textEditorModel.getOptions();
522			validatedOptions = {
523				tabSize: modelOptions.tabSize,
524				insertSpaces: modelOptions.insertSpaces
525			};
526		}
527	
528		return validatedOptions;
529	}
