35	export function getRealAndSyntheticDocumentFormattersOrdered(
36		documentFormattingEditProvider: LanguageFeatureRegistry<DocumentFormattingEditProvider>,
37		documentRangeFormattingEditProvider: LanguageFeatureRegistry<DocumentRangeFormattingEditProvider>,
38		model: ITextModel
39	): DocumentFormattingEditProvider[] {
40		const result: DocumentFormattingEditProvider[] = [];
41		const seen = new ExtensionIdentifierSet();
42	
43		// (1) add all document formatter
44		const docFormatter = documentFormattingEditProvider.ordered(model);
45		for (const formatter of docFormatter) {
46			result.push(formatter);
47			if (formatter.extensionId) {
48				seen.add(formatter.extensionId);
49			}
50		}
51	
52		// (2) add all range formatter as document formatter (unless the same extension already did that)
53		const rangeFormatter = documentRangeFormattingEditProvider.ordered(model);
54		for (const formatter of rangeFormatter) {
55			if (formatter.extensionId) {
56				if (seen.has(formatter.extensionId)) {
57					continue;
